-- Seed: importa os 100 registos da sheet CONTROL (BMW Business Control · Aveiro)
-- para a tabela public.control_records (tab "database").
-- Importação única. Corre no Supabase SQL Editor (Project > SQL Editor > New query).
-- Guarda contra duplicados: aborta se a tabela já tiver linhas.

BEGIN;

DO $$
BEGIN
  IF (SELECT count(*) FROM public.control_records) > 0 THEN
    RAISE EXCEPTION 'control_records já tem dados — importação cancelada para evitar duplicados. Se queres reimportar, apaga primeiro os registos existentes.';
  END IF;
END $$;


COMMIT;
